class Solution:
    def encode(self, s: str) -> str:
        from functools import lru_cache

        @lru_cache(maxsize=None)
        def dp(i, j):
            cur = s[i:j+1]
            if j - i < 4:
                return cur
            best = cur
            for m in range(i + 1, j + 1):
                cand = dp(i, m - 1) + dp(m, j)
                if len(cand) < len(best):
                    best = cand
            p = (cur + cur).find(cur, 1)
            if p < len(cur):
                cnt = len(cur) // p
                cand = str(cnt) + '[' + dp(i, i + p - 1) + ']'
                if len(cand) < len(best):
                    best = cand
            return best

        return dp(0, len(s) - 1)

