class Solution {
    unordered_map<long long, string> memo;
    string s;
    string dp(int i, int j) {
        long long key = (long long)i * 1000 + j;
        auto it = memo.find(key);
        if (it != memo.end()) return it->second;
        string cur = s.substr(i, j - i + 1);
        if ((int)cur.size() < 5) return memo[key] = cur;
        string best = cur;
        for (int m = i + 1; m <= j; ++m) {
            string cand = dp(i, m - 1) + dp(m, j);
            if (cand.size() < best.size()) best = cand;
        }
        string doubled = cur + cur;
        size_t p = doubled.find(cur, 1);
        if (p != string::npos && p < cur.size()) {
            int cnt = cur.size() / p;
            string cand = to_string(cnt) + "[" + dp(i, i + p - 1) + "]";
            if (cand.size() < best.size()) best = cand;
        }
        return memo[key] = best;
    }
public:
    string encode(string str) {
        s = str;
        return dp(0, (int)s.size() - 1);
    }
};

