class Solution {
    private Map<Long, String> memo = new HashMap<>();
    private String s;

    private String dp(int i, int j) {
        long key = (long) i * 1000 + j;
        String cached = memo.get(key);
        if (cached != null) return cached;
        String cur = s.substring(i, j + 1);
        if (cur.length() < 5) return memo.put(key, cur);
        String best = cur;
        for (int m = i + 1; m <= j; m++) {
            String cand = dp(i, m - 1) + dp(m, j);
            if (cand.length() < best.length()) best = cand;
        }
        int p = (cur + cur).indexOf(cur, 1);
        if (p > 0 && p < cur.length()) {
            int cnt = cur.length() / p;
            String cand = cnt + "[" + dp(i, i + p - 1) + "]";
            if (cand.length() < best.length()) best = cand;
        }
        memo.put(key, best);
        return best;
    }

    public String encode(String str) {
        s = str;
        return dp(0, s.length() - 1);
    }
}

