class Solution:
    def encode(self, s: str) -> str:
        n = len(s)
        dp = [[None] * n for _ in range(n)]
        for L in range(1, n + 1):
            for i in range(n - L + 1):
                j = i + L - 1
                cur = s[i:j+1]
                if L < 5:
                    dp[i][j] = cur
                    continue
                best = cur
                for m in range(i + 1, j + 1):
                    cand = dp[i][m-1] + dp[m][j]
                    if len(cand) < len(best):
                        best = cand
                p = (cur + cur).find(cur, 1)
                if p < L:
                    cand = str(L // p) + '[' + dp[i][i+p-1] + ']'
                    if len(cand) < len(best):
                        best = cand
                dp[i][j] = best
        return dp[0][n-1]

