public:
    string encode(string s) {
        int n = s.size();
        vector<vector<string>> dp(n, vector<string>(n));
        for (int L = 1; L <= n; ++L) {
            for (int i = 0; i + L <= n; ++i) {
                int j = i + L - 1;
                string cur = s.substr(i, L);
                if (L < 5) { dp[i][j] = cur; continue; }
                string best = cur;
                for (int m = i + 1; m <= j; ++m) {
                    string cand = dp[i][m-1] + dp[m][j];
                    if (cand.size() < best.size()) best = cand;
                }
                string doubled = cur + cur;
                size_t p = doubled.find(cur, 1);
                if (p != string::npos && p < (size_t)L) {
                    string cand = to_string(L / p) + "[" + dp[i][i + p - 1] + "]";
                    if (cand.size() < best.size()) best = cand;
                }
                dp[i][j] = best;
            }
        }
        return dp[0][n-1];
    }
};

